INSERT INTO bi_report_definition (
    report_id, tenant_id, report_code, report_name, report_type, data_source, query_text,
    permission_code, data_level, description, created_at, updated_at
) VALUES (
    #{reportId}, #{tenantId}, #{reportCode}, #{reportName}, #{reportType}, #{dataSource}, #{queryText},
    #{permissionCode}, #{dataLevel}, #{description}, #{createdAt}, #{updatedAt}
)

mapper.select:
SELECT report_id, tenant_id, report_code, report_name, report_type, data_source, query_text,
       permission_code, data_level, description, created_at, updated_at
FROM bi_report_definition
WHERE tenant_id = #{tenantId}
  AND report_id = #{reportId}

SELECT report_id, tenant_id, report_code, report_name, report_type, data_source, query_text,
       permission_code, data_level, description, created_at, updated_at
FROM bi_report_definition
WHERE tenant_id = #{tenantId}
  AND report_code = #{reportCode}

SELECT report_id, tenant_id, report_code, report_name, report_type, data_source, query_text,
       permission_code, data_level, description, created_at, updated_at
FROM bi_report_definition
WHERE tenant_id = #{tenantId}
  AND report_type = #{reportType}
ORDER BY created_at DESC

