FROM bi_kpi_metric
WHERE tenant_id = #{tenantId}
  AND category = #{category}
ORDER BY measured_at DESC, kpi_code ASC

SELECT kpi_id, tenant_id, kpi_code, kpi_name, category, value, target_value, unit, status, measured_at
FROM bi_kpi_metric
WHERE tenant_id = #{tenantId}
  AND kpi_code = #{kpiCode}
ORDER BY measured_at DESC
